import csv
import io

from fastapi import APIRouter
from fastapi.responses import StreamingResponse

from .db import get_db

router = APIRouter()
PAGE = 500
COLUMNS = ["invoice_id", "customer_id", "amount", "issued_at"]


def _pages(tenant_id: str):
    last = None
    while True:
        query = {"tenant_id": tenant_id, **({"_id": {"$gt": last}} if last else {})}
        page = list(get_db().invoices.find(query).sort("_id", 1).limit(PAGE))
        if not page:
            return
        last = page[-1]["_id"]
        yield page


def _rows(tenant_id: str):
    buf = io.StringIO()
    writer = csv.DictWriter(buf, fieldnames=COLUMNS)
    writer.writeheader()
    for page in _pages(tenant_id):
        writer.writerows(page)
        yield buf.getvalue()
        buf.seek(0)
        buf.truncate(0)


@router.get("/exports/invoices.csv")
def build_csv(tenant_id: str) -> StreamingResponse:
    return StreamingResponse(_rows(tenant_id), media_type="text/csv")
